fn bitwise_and(x1: &Vec<u8>, x2: &Vec<u8>) -> Vec<u8> {
    // Ensure both inputs have the same length
    assert_eq!(x1.len(), x2.len(), "Input vectors must have the same length");

    // Compute bitwise AND for each pair of elements
    x1.iter()
      .zip(x2.iter())
      .map(|(&a, &b)| a & b)
      .collect()
}

fn main() {
    let a = vec![0b1100_1100, 0b1010_1010, 0b1111_0000];
    let b = vec![0b1010_1010, 0b1100_1100, 0b1111_1111];

    let result = bitwise_and(&a, &b);
    println!("{:08b?}", result);
    // Output: ["1000_1000", "1000_1000", "1111_0000"]
}